2212			\big(\hat{M}^{(\mathrm{Point},X),x}_{a}\,
2213			\hat{M}^{(\mathrm{Point},Z),z}_{b}\,
2214			\hat{M}^{(\mathrm{Point},X),x}_{a}
2215			\big)_{\mathsf{B}\mathsf{A}''}\,.
2216		\]
