  1089		\[
  1090			\mathrm{combine}_{f,g}(x, z, \alpha, \beta)
  1091			= \alpha f(x) + \beta g(z)\,,
  1092			\qquad x \in \F_q^m,\ z \in \F_q^m,\ \alpha \in \F_q,\
